-- Chỉ mục cho cửa hàng nhiều dữ liệu (tạo bởi scripts, xem lịch sử git).
-- 1) Ngày bán: báo cáo / danh sách lọc theo (SaleDate ?? CreatedAt) = COALESCE("SaleDate","CreatedAt")
--    → chỉ mục biểu thức đúng y hệt; trước đây quét toàn bộ đơn của cửa hàng cả khi xem «hôm nay».
CREATE INDEX IF NOT EXISTS "IX_PosSaleOrders_Store_SaleDay"
    ON "PosSaleOrders" ("StoreId", (COALESCE("SaleDate", "CreatedAt")));
CREATE INDEX IF NOT EXISTS "IX_PosSaleOrders_Store_Status_SaleDay"
    ON "PosSaleOrders" ("StoreId", "Status", (COALESCE("SaleDate", "CreatedAt")));
-- 2) Tìm không dấu (VnSearch.Has → translate(lower(x),…) LIKE '%từ khóa%'): GIN pg_trgm.
--    Thiếu extension → các lệnh dưới bị bỏ qua (khởi động vẫn chạy), tìm kiếm chạy như cũ.
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX IF NOT EXISTS "IX_PosProducts_Name_VnTrgm" ON "PosProducts" USING gin (translate(lower("Name"), 'àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđÀÁẠẢÃÂẦẤẬẨẪĂẰẮẶẲẴÈÉẸẺẼÊỀẾỆỂỄÌÍỊỈĨÒÓỌỎÕÔỒỐỘỔỖƠỜỚỢỞỠÙÚỤỦŨƯỪỨỰỬỮỲÝỴỶỸĐ̛̣̀́̃̉̂̆', 'aaaaaaaaaaaaaaaaaeeeeeeeeeeeiiiiiooooooooooooooooouuuuuuuuuuuyyyyydaaaaaaaaaaaaaaaaaeeeeeeeeeeeiiiiiooooooooooooooooouuuuuuuuuuuyyyyyd') gin_trgm_ops);
