-- 3) Ghi chú nội bộ sổ quỹ: EF dịch StartsWith(marker) thành LIKE 'marker%' — thanh toán / hủy đơn tìm dòng
--    thu theo marker (mỗi lần thanh toán) trước đây quét toàn bộ sổ quỹ cửa hàng. GIN chịu được ghi chú dài.
CREATE INDEX IF NOT EXISTS "IX_CashTransactions_InternalNote_Trgm" ON "CashTransactions" USING gin ("InternalNote" gin_trgm_ops);
